FORMAS_PADRAO = [
    ("Dinheiro", "dinheiro", "💵"),
    ("Pix", "pix", "⚡"),
    ("Cartão de débito", "debito", "💳"),
    ("Cartão de crédito", "credito", "💳"),
    ("Transferência", "transferencia", "🏦"),
    ("Boleto", "boleto", "🧾"),
]
TIPOS_ENTRADA_PADRAO = [
    ("Salário", "💼", "#d4ff3f"),
    ("Freelance", "🧑‍💻", "#4fd4ff"),
    ("Investimentos", "📈", "#4fff88"),
    ("Presente", "🎁", "#ff4fd4"),
    ("Outros", "💵", "#a0a0a0"),
]


def criar_cadastros_padrao(apps, schema_editor):
    """Cria formas de pagamento e tipos de entrada padrão para os usuários
    existentes e converte o texto antigo de forma de pagamento no novo FK."""
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    PaymentMethod = apps.get_model("finance", "PaymentMethod")
    IncomeType = apps.get_model("finance", "IncomeType")
    Transaction = apps.get_model("finance", "Transaction")

    for user in User.objects.all():
        por_kind = {}
        for nome, kind, icone in FORMAS_PADRAO:
            por_kind[kind] = PaymentMethod.objects.create(user=user, name=nome, kind=kind, icon=icone)
        for nome, icone, cor in TIPOS_ENTRADA_PADRAO:
            IncomeType.objects.create(user=user, name=nome, icon=icone, color=cor)

        for tx in Transaction.objects.filter(user=user).exclude(legacy_payment_method=""):
            metodo = por_kind.get(tx.legacy_payment_method)
            if metodo is None:
                metodo, _ = PaymentMethod.objects.get_or_create(
                    user=user, kind="outro", defaults={"name": "Outro", "icon": "💳"}
                )
            tx.payment_method = metodo
            tx.save(update_fields=["payment_method"])


